on conflict (seq) do update set
  ta = excluded.ta,
  ps_seca = excluded.ps_seca,
  ps_cheia = excluded.ps_cheia,
  emb_seca = excluded.emb_seca,
  emb_cheia = excluded.emb_cheia;
